#!/usr/bin/env node
// Installs the local pre-commit hook. Git does not track .git/hooks, so this
// script is the tracked source of truth. Re-run after cloning: npm run hooks:install
import { execFileSync } from "node:child_process";
import { chmodSync, mkdirSync, writeFileSync } from "node:fs";
import path from "node:path";

export const HOOK_CONTENT = `#!/bin/sh
# Generated by scripts/install_hooks.mjs. Re-install with: npm run hooks:install
# Bypass once: git commit --no-verify

if [ -d ".projectmem" ] && command -v pjm >/dev/null 2>&1; then
    pjm precheck --level warn || true
fi

if [ -f package.json ]; then
    CHECK_LOG="\${TMPDIR:-/tmp}/galway-pre-commit.log"
    if ! npm run check:lint --silent >"$CHECK_LOG" 2>&1; then
        cat "$CHECK_LOG"
        echo "Pre-commit lint failed. Fix the errors or use git commit --no-verify."
        exit 1
    fi
    STAGED="$(git diff --cached --name-only)"
    if printf '%s\\n' "$STAGED" | grep -Eq '^(src/|tests/|scripts/|index\\.html|package(-lock)?\\.json)'; then
        if ! npm test --silent >"$CHECK_LOG" 2>&1; then
            tail -60 "$CHECK_LOG"
            echo "Pre-commit tests failed. Fix the failures or use git commit --no-verify."
            exit 1
        fi
    fi
    rm -f "$CHECK_LOG"
fi
`;

export function resolveHookPath(exec = execFileSync) {
  const hooksDir = exec("git", ["rev-parse", "--git-path", "hooks"], { encoding: "utf8" }).trim();
  return path.resolve(hooksDir, "pre-commit");
}

export function installHooks({ exec = execFileSync, log = console.log } = {}) {
  const target = resolveHookPath(exec);
  mkdirSync(path.dirname(target), { recursive: true });
  writeFileSync(target, HOOK_CONTENT, "utf8");
  chmodSync(target, 0o755);
  log(`Installed pre-commit hook at ${target}`);
  return target;
}

if (process.argv[1] && import.meta.url === `file://${path.resolve(process.argv[1])}`) {
  installHooks();
}
